func (q *Queries) UpsertWatchProgress(ctx context.Context, arg UpsertWatchProgressParams) error {
	_, err := q.db.Exec(ctx, upsertWatchProgress,
		arg.UserID,
		arg.RecordingID,
		arg.PositionMs,
		arg.Now,
	)
	return err
}
